231	function writeSessionHint(present: boolean): void {
232	  try {
233	    if (present) window.localStorage.setItem(SESSION_HINT_KEY, "1");
234	    else window.localStorage.removeItem(SESSION_HINT_KEY);
235	  } catch {
236	    // Storage blocked -- the returning-visitor fast path simply won't apply.
237	  }
