240	export default function App() {
241	  const { isLoading, isAuthenticated } = useConvexAuth();
242	
243	  // The hash is tracked live so a "Sign in" tap on the waitlist (or the back
244	  // button) re-routes in place, without a reload.
245	  const [hash, setHash] = useState(() => window.location.hash);
246	  useEffect(() => {
247	    const onHashChange = () => setHash(window.location.hash);
248	    window.addEventListener("hashchange", onHashChange);
249	    return () => window.removeEventListener("hashchange", onHashChange);
250	  }, []);
251	
252	  // Read once at first paint -- it only steers the frame before Clerk resolves;
253	  // after that, isAuthenticated drives the choice.
254	  const [hasSessionHint] = useState(readSessionHint);
255	
256	  // Keep the hint honest against the resolved auth state: set it when signed in,
257	  // clear it the moment we resolve signed out -- covering both a sign-out and a
258	  // stale hint whose session no longer holds. Left untouched while auth loads.
259	  useEffect(() => {
260	    if (isLoading) return;
261	    writeSessionHint(isAuthenticated);
262	  }, [isLoading, isAuthenticated]);
263	
264	  const view = resolveView({ isAuthenticated, isLoading, hash, hasSessionHint });
265	  if (view === "home") return <Home />;
266	  if (view === "signin") return <SignIn />;
